//! How a column default renders on Postgres.

use std::borrow::Cow;

use crate::ir::{ColumnDefault, GeneratedDefault};

/// The `DEFAULT` expression, or `None` when the column gets no database
/// default: a `dbgenerated()` marker (the default lives outside
/// cratestack), or `cuid()`, which has no Postgres equivalent and is
/// generated by cratestack alone.
pub(super) fn render_default(default: &ColumnDefault) -> Option<Cow<'_, str>> {
    match default {
        ColumnDefault::Literal(value) | ColumnDefault::Function(value) => Some(value.into()),
        ColumnDefault::Generated(GeneratedDefault::Now) => Some("now()".into()),
        // Built into Postgres since 13; pgcrypto provided it before.
        ColumnDefault::Generated(GeneratedDefault::Uuid) => Some("gen_random_uuid()".into()),
        ColumnDefault::Generated(GeneratedDefault::Cuid) | ColumnDefault::DbGenerated => None,
    }
}
